"""Curated, evidence-linked Phase 1.1 editorial layer for Game 1.

The fixture builder calls this after it has normalized the raw completed-game
artifacts.  Keeping the prose here means the reader consumes fixture data,
rather than a presentation-only copy of the campaign narrative.
"""
from __future__ import annotations


def apply_editorial(bundle: dict) -> None:
    """Add optional Game 1 editorial content and resolve every source reference."""
    evidence = bundle["evidence_index"]
    phases = {phase["phase_id"]: phase for year in bundle["years"] for phase in year["phases"]}

    def phase_source(phase_id: str, kind: str) -> str:
        return next(source_id for source_id in phases[phase_id]["source_refs"] if evidence[source_id]["kind"] == kind)

    def public(phase_id: str, label: str, kind: str = "adjudication") -> dict:
        source_ref = phase_source(phase_id, kind)
        return {"source_ref": source_ref, "label": label, "evidence_type": "public", "target": {"type": "source", "id": source_ref}}

    def postgame(label: str) -> dict:
        source_ref = bundle["summary"]["chronology_source_ref"]
        return {"source_ref": source_ref, "label": label, "evidence_type": "postgame", "target": {"type": "source", "id": source_ref}}

    def message(message_id: str, label: str) -> dict:
        item = bundle["messages"][message_id]
        return {"source_ref": item["source_ref"], "label": label, "evidence_type": "message", "target": {"type": "message", "id": message_id}}

    def record(record_id: str, label: str) -> dict:
        item = bundle["private_records"][record_id]
        return {"source_ref": item["source_ref"], "label": label, "evidence_type": "private_record", "target": {"type": "record", "id": record_id}}

    def order(order_id: str, label: str) -> dict:
        item = bundle["orders"][order_id]
        return {"source_ref": item["source_ref"], "label": label, "evidence_type": "public", "target": {"type": "order", "id": order_id}}

    def claim(text: str, *citations: dict) -> dict:
        return {"text": text, "citations": list(citations)}

    def section(heading: str, paragraphs: list[dict], bridge: dict) -> dict:
        return {"heading": heading, "claims": paragraphs, "bridge": bridge}

    bundle["summary"]["editorial"] = {
        "title": "Game 1: the long eastern contest",
        "executive_history": [
            claim("Game 1 ran through the scheduled 1910 cutoff. Russia, played by Shaver, finished first on 12 supply centers; the record does not classify the result as a solo victory.", postgame("Postgame chronology and recorded outcome")),
            claim("The campaign did not turn on one durable alliance. Its public record instead shows repeated local bargains, contested borders, and changing concentrations of force across the Balkans, the Mediterranean, and the western front.", postgame("Postgame chronology"), public("1902_fall_movement", "Fall 1902 public adjudication")),
            claim("In 1902, Austria’s attempt to recover leverage in the east collided with Russian pressure, while Turkey converted the Greek position and Italy moved a fleet into the eastern Mediterranean. Those results left several powers with choices rather than a settled coalition.", public("1902_spring_movement", "Spring 1902 public adjudication"), public("1902_fall_movement", "Fall 1902 public adjudication")),
            claim("Later public transitions, including France taking Munich from Germany in Fall 1906, belong to that wider evolving record. They are evidence of a change on the board, not proof that any one earlier message caused it.", public("1906_fall_retreat", "Fall 1906 board transition"), postgame("Postgame chronology")),
        ],
        "turning_points": [
            {
                "title": "The Balkan pressure becomes visible",
                "claims": [claim("Austria’s Spring 1902 attack dislodged Russia from Galicia, but the fall saw Russia take Budapest and Galicia while Turkey took Greece. The reversal is public board evidence, not a single-cause explanation.", public("1902_spring_movement", "Spring 1902 adjudication"), public("1902_fall_movement", "Fall 1902 adjudication"))],
            },
            {
                "title": "Italy’s eastern option opens, but does not settle",
                "claims": [claim("Italy moved Naples to Tyrrhenian Sea in spring and Ionian Sea to Eastern Mediterranean in fall. The Tyrrhenian fleet did not enter Ionian Sea, leaving that sea vacant in the fall after-state; that outcome narrowed neither the future Adriatic nor eastern-Mediterranean choice to one proven path.", order("1902_spring_movement:unit_0031", "Italy’s Spring 1902 fleet order"), order("1902_fall_movement:unit_0015", "Italy’s Fall 1902 Eastern Mediterranean order"), public("1902_fall_movement", "Fall 1902 board after-state"))],
            },
            {
                "title": "Words and orders diverge in the eastern Mediterranean",
                "claims": [claim("Turkey’s spring message to Italy described Smyrna’s fleet as Balkan flexibility and proposed mutual stay-out in Ionian, Aegean, and Eastern Mediterranean; the public order moved that fleet to Aegean. This is a message-to-order comparison, not access to a shared private understanding.", message("1902_spring_negotiation_major_2", "Message from Major to Birsan"), order("1902_spring_movement:unit_0034", "Turkey’s Spring 1902 fleet order"))],
            },
            {
                "title": "Winter confirms a contested, not closed, theater",
                "claims": [claim("Austria disbanded one unit and Turkey built a fleet in Smyrna in Winter 1902. The publicly recorded adjustments altered the available force without deciding where the next campaign would break.", order("1902_winter_adjustment:adjustment::austria", "Austria’s Winter 1902 disband"), order("1902_winter_adjustment:adjustment::turkey", "Turkey’s Winter 1902 build"))],
            },
        ],
        "power_dossiers": [
            {"power": "austria", "agent_id": "helena", "note": claim("Helena’s Austria entered 1902 trying to hold a quiet Italian border while contesting Russia in the Balkans. The proposal was private; the later public orders show Trieste held in spring and Austria’s eastern position under pressure by fall.", message("1902_spring_negotiation_helena_0", "Message from Helena to Birsan"), public("1902_fall_movement", "Fall 1902 Austrian results"))},
            {"power": "england", "agent_id": "victor", "note": claim("Victor’s England remained a northern power in the 1902 scene. Its public moves kept the reader’s featured eastern contest at a distance rather than establishing an editorial claim about a hidden coalition.", public("1902_spring_movement", "Spring 1902 public adjudication"), public("1902_fall_movement", "Fall 1902 public adjudication"))},
            {"power": "france", "agent_id": "seraphine", "note": claim("Seraphine’s France was a western and central presence in this chapter. A private Italy–France request for a quiet Alpine border is shown as a proposal; the relevant orders leave Marseilles holding in both 1902 movements.", message("1902_spring_negotiation_seraphine_2", "Message from Seraphine to Birsan"), order("1902_fall_movement:unit_0028", "France’s Fall 1902 Marseilles order"))},
            {"power": "germany", "agent_id": "marcellus", "note": claim("Marcellus’s Germany was positioned in the northern-central board while the 1902 narrative foregrounds the Balkans and Mediterranean. Its orders are available as public evidence without assigning it an unrecorded role in the eastern contest.", public("1902_fall_movement", "Fall 1902 public adjudication"))},
            {"power": "italy", "agent_id": "birsan", "note": claim("Birsan’s Italy held Venice and Tunis in 1902 while its fleets shifted from Naples to Tyrrhenian Sea and then from Ionian Sea to Eastern Mediterranean. Italy’s private reflection describes its own assessment; it is not presented as knowledge held by the other players.", public("1902_spring_movement", "Spring 1902 Italian orders"), record("1902_fall_movement:birsan:reflection", "Birsan’s private post-fall reflection"))},
            {"power": "russia", "agent_id": "shaver", "note": claim("Shaver’s Russia finished the full campaign as the 12-center leader without a recorded solo. In 1902 its public fall moves took Budapest and Galicia, placing it directly in Austria’s shrinking eastern space.", postgame("Recorded Game 1 outcome"), public("1902_fall_movement", "Fall 1902 public adjudication"))},
            {"power": "turkey", "agent_id": "major", "note": claim("Major’s Turkey moved its Smyrna fleet to Aegean in spring, took Greece in fall, and built a Smyrna fleet in winter. These results ground the dossier; the associated messages remain proposals rather than proof of motives.", public("1902_spring_movement", "Spring 1902 Turkish fleet move"), public("1902_fall_movement", "Fall 1902 Greek result"), public("1902_winter_adjustment", "Winter 1902 Turkish build"))},
        ],
    }
    bundle["strategic_arcs"] = [
        {"title": "Austria and Russia: a disputed Balkan hinge", "claims": [claim("The 1902 sequence reverses the Galician contest: Austria’s spring move dislodged Russia there, then Russia’s fall orders recovered Galicia and moved into Budapest. That public sequence frames the arc without reducing it to a claim about private intent.", public("1902_spring_movement", "Spring 1902 adjudication"), public("1902_fall_movement", "Fall 1902 adjudication"))]},
        {"title": "Italy and Turkey: Mediterranean space becomes contested", "claims": [claim("Italy’s fleet reached Eastern Mediterranean in fall as Turkey took Greece with Aegean support. A spring message proposed a stay-out line, but the reader treats the message and the adjudicated orders as distinct evidence types.", message("1902_spring_negotiation_major_2", "Message from Major to Birsan"), public("1902_fall_movement", "Fall 1902 adjudication"))]},
        {"title": "Italy and Austria: a cheap border under changing pressure", "claims": [claim("Both sides exchanged private Ven/Tri/Adr hands-off proposals and the public 1902 movement orders kept Venice and Trieste from attacking one another. That demonstrates a low-cost border for the year, not a durable alliance.", message("1902_spring_negotiation_helena_0", "Message from Helena to Birsan"), public("1902_fall_movement", "Fall 1902 public orders"))]},
        {"title": "The western front keeps moving", "claims": [claim("France’s Fall 1906 acquisition of Munich from Germany is a later public board transition. It is included as a counterweight to a story that would treat 1902’s east as the whole campaign.", public("1906_fall_retreat", "Fall 1906 board transition"))]},
    ]

    phases["1902_spring_movement"]["narrative"]["editorial"] = {
        "sections": [
            section("A. Situation entering Spring", [claim("The year opened with Italy holding Venice, Ionian Sea, and Tunis while Austria occupied Trieste, Serbia, Greece, Budapest, and Vienna. Russia still stood in Galicia and Rumania, so the Austro-Russian contact zone ran through the Balkans rather than through a settled partition. The public before-state establishes that geography; it does not reveal what any player knew about another player’s private record.", public("1902_spring_movement", "Spring 1902 board before-state")), claim("Italy’s northern border was therefore valuable mainly because it could stay quiet. A quiet Venice–Trieste edge would let Italian units look outward, while any contest there could redirect attention from the fleet route south and east. That is a description of the board’s options, not a prediction that either neighbor would honor a proposal.", public("1902_spring_movement", "Spring 1902 board before-state"))], claim("That board made the opening negotiation consequential, but the orders—not the messages—would decide whether the space stayed cheap." , public("1902_spring_movement", "Spring 1902 public adjudication"))),
            section("B. Intentions, beliefs, and plans", [claim("Helena told Birsan that Austria would keep Trieste defensive, avoid Venice and the Adriatic, cover Galicia, and press Rumania. The message is evidence of Helena’s stated plan to Birsan only; it is not evidence that Russia, Turkey, or France received or accepted that plan.", message("1902_spring_negotiation_helena_0", "Message from Helena to Birsan")), claim("Birsan’s private reflection after the phase later described an Italian aim of keeping Venice, Trieste, and Piedmont inexpensive while using the Ionian and Tyrrhenian fleets to seek a second center. That reflection is a postgame-private record of Birsan’s assessment, not a contemporaneous fact known to the other powers.", record("1902_spring_movement:birsan:reflection", "Birsan’s private Spring reflection"))], claim("The distinction matters: declared boundaries and private assessments supplied possibilities, while the public result supplied the test." , public("1902_spring_movement", "Spring 1902 public adjudication"))),
            section("C. Diplomacy and commitments", [claim("The Austria–Italy exchange named a Ven/Tri/Adr hands-off arrangement. Separately, Major told Birsan that Smyrna’s fleet was for Black Sea and Balkan flexibility and proposed mutual stay-out from Ionian, Aegean, and Eastern Mediterranean. Each is an addressed private message, so neither can by itself prove an alliance, a promise kept, or an intention shared beyond its recipients.", message("1902_spring_negotiation_helena_0", "Message from Helena to Birsan"), message("1902_spring_negotiation_major_2", "Message from Major to Birsan")), claim("Russia’s Shaver also described Austrian pressure around Galicia and Rumania when writing to Birsan. That message adds a contemporary Russian view of the eastern danger, but the reader keeps it separate from the board evidence that follows.", message("1902_spring_negotiation_shaver_3", "Message from Shaver to Birsan"))], claim("The commitments were thus useful reading context, not a substitute for adjudication." , public("1902_spring_movement", "Spring 1902 public adjudication"))),
            section("D. Orders and adjudicated result", [claim("Austria held Trieste and sent Budapest to Galicia with support from Vienna. The move dislodged Russia’s Galicia army. Austria also ordered Serbia to Rumania, while Russia’s supported Galicia-to-Budapest attempt did not take Budapest. These are public orders and results, not editorial inference.", order("1902_spring_movement:unit_0001", "Austria’s Spring Trieste order"), order("1902_spring_movement:unit_0023", "Austria’s Spring Budapest-to-Galicia order"), public("1902_spring_movement", "Spring 1902 public adjudication")), claim("Italy held Venice, Ionian Sea, and Tunis, and moved Naples to Tyrrhenian Sea. Turkey moved Smyrna to Aegean despite the earlier message’s description of a stay-out line. The juxtaposition is a documented message/order difference; it does not resolve why Turkey made the move.", order("1902_spring_movement:unit_0031", "Italy’s Spring Naples-to-Tyrrhenian order"), order("1902_spring_movement:unit_0034", "Turkey’s Spring Smyrna-to-Aegean order"), message("1902_spring_negotiation_major_2", "Message from Major to Birsan"))], claim("Spring ended with a proved Austrian gain in Galicia, a preserved Italian northern border, and a newly visible Turkish fleet position." , public("1902_spring_movement", "Spring 1902 board after-state"))),
            section("E. Reactions and what changed", [claim("Birsan’s private review treated the held Venice–Trieste border as demonstrated low cost for that season and treated the Aegean entry as reason to reassess the Mediterranean. That is Birsan’s own recorded interpretation. Publicly, the relevant facts were simpler: Austria had displaced Russia from Galicia, Turkey was in Aegean, and Italy now had a fleet in Tyrrhenian Sea.", record("1902_spring_movement:birsan:reflection", "Birsan’s private Spring reflection"), public("1902_spring_movement", "Spring 1902 public adjudication")), claim("No supply-center ownership changed in the movement phase, so the immediate effect was positional rather than a build. The fall would show whether Austria could convert pressure on Russia and whether Italy’s fleet movement would become leverage or merely an unfinished route.", public("1902_spring_movement", "Spring 1902 public adjudication"))], claim("Fall inherits the same borders, but with Galicia displaced and the Aegean fleet now part of the calculation." , public("1902_spring_movement", "Spring 1902 board after-state"))),
        ]
    }

    phases["1902_fall_movement"]["narrative"]["editorial"] = {
        "sections": [
            section("A. Situation entering Fall", [claim("Fall began after Austria had dislodged Russia from Galicia, but the board still contained active Russian armies in Rumania, Warsaw, Moscow, and the retreating Galicia unit. Italy had kept Venice, Ionian Sea, and Tunis secure while adding a fleet in Tyrrhenian Sea; Turkey’s fleet now occupied Aegean. The public before-state made the Balkan and eastern-Mediterranean intersections sharper without determining the coming orders.", public("1902_fall_movement", "Fall 1902 board before-state")), claim("Austria’s eastern position was exposed to more than one direction. Russia could contest Budapest, Galicia, and Vienna while Turkey had a route into Greece. Italy’s own units were not yet in the Balkans, but their location gave it a choice between preserving a cheap northern boundary and committing farther east.", public("1902_fall_movement", "Fall 1902 board before-state"))], claim("The issue was no longer whether forces could reach the area, but which moves would actually resolve." , public("1902_fall_movement", "Fall 1902 public adjudication"))),
            section("B. Intentions, beliefs, and plans", [claim("Helena again proposed a Venice–Trieste–Adriatic hands-off arrangement to Birsan and described Austria as contesting Russia from Galicia and Serbia. This is a private proposal between those two agents, not a public commitment binding either power or evidence of a common plan with Turkey.", message("1902_fall_negotiation_helena_0", "Message from Helena to Birsan")), claim("Birsan’s later private reflection characterized Italy’s objective as keeping Piedmont and Venice inexpensive while turning the eastern fleet position into a second-center route. The record displays this as Birsan’s private assessment after adjudication, carefully distinct from claims about the beliefs of Austria, Russia, Turkey, or France.", record("1902_fall_movement:birsan:reflection", "Birsan’s private Fall reflection"))], claim("The fall scene therefore carries competing intentions into the orders, not a settled shared strategy." , public("1902_fall_movement", "Fall 1902 public adjudication"))),
            section("C. Diplomacy and commitments", [claim("Major told Birsan that Aegean was meant as Balkan pressure and offered to stay out of Ionian and Tyrrhenian Sea if Italy respected the corresponding line. Birsan replied by asking for clarity after the spring Aegean move. Both messages are preserved correspondence: they reveal what was said in that thread, not a guarantee that either side would act as proposed.", message("1902_fall_negotiation_major_2", "Message from Major to Birsan"), message("1902_fall_negotiation_birsan_1", "Message from Birsan to Major")), claim("Shaver told Birsan that Russia planned pressure on Budapest and Galicia, and Birsan replied that he would hold Venice defensively while Austria could not freely turn west. These communications identify offers and perceptions, but the later Russian moves remain the evidence for what actually happened.", message("1902_fall_negotiation_shaver_2", "Message from Shaver to Birsan"), message("1902_fall_negotiation_birsan_3", "Message from Birsan to Shaver"))], claim("The board would expose overlapping pressure without letting correspondence stand in for causation." , public("1902_fall_movement", "Fall 1902 public adjudication"))),
            section("D. Orders and adjudicated result", [claim("Russia moved Rumania to Budapest and Warsaw to Galicia with Ukrainian support. Austria’s Galicia army was dislodged, and its Greek fleet was dislodged as Turkey moved Bulgaria to Greece with Aegean support. The same adjudication records no supply-center ownership changes during the movement phase itself.", order("1902_fall_movement:unit_0016", "Russia’s Fall Rumania-to-Budapest order"), order("1902_fall_movement:unit_0033", "Russia’s Fall Warsaw-to-Galicia order"), order("1902_fall_movement:unit_0020", "Turkey’s Fall Bulgaria-to-Greece order"), public("1902_fall_movement", "Fall 1902 public adjudication")), claim("Italy held Venice and Tunis, moved Ionian Sea to Eastern Mediterranean, and ordered Tyrrhenian Sea to Ionian Sea. The adjudicated after-state places the first fleet in Eastern Mediterranean and leaves the Tyrrhenian fleet in place, so Ionian Sea was vacant. Austria’s Trieste supported Vienna and did not attack Venice.", order("1902_fall_movement:unit_0015", "Italy’s Fall Ionian-to-Eastern Mediterranean order"), order("1902_fall_movement:unit_0031", "Italy’s Fall Tyrrhenian-to-Ionian order"), public("1902_fall_movement", "Fall 1902 board after-state"))], claim("The result was a positional reversal around Austria and a more direct Italian–Turkish fleet contact, without an immediate build." , public("1902_fall_movement", "Fall 1902 public adjudication"))),
            section("E. Reactions and what changed", [claim("The public aftermath was stark: Russia held Budapest and Galicia, Turkey occupied Greece, Austria had two dislodged units, Italy had a fleet in Eastern Mediterranean, and the Ionian Sea was unoccupied. These facts show an Austrian setback and a contested maritime area, but they cannot determine a single necessary response for any power.", public("1902_fall_movement", "Fall 1902 board after-state")), claim("Birsan’s private reflection saw Austria’s collapse and the Eastern Mediterranean entry as an opening while also noting the Ionian gap. That is a useful authored reaction attached to its private evidence drawer; it is not a claim that other players shared the diagnosis.", record("1902_fall_movement:birsan:reflection", "Birsan’s private Fall reflection"))], claim("Winter adjustments would now convert the fall board into durable force—or reveal its remaining limits." , public("1902_fall_movement", "Fall 1902 board after-state"))),
        ]
    }

    phases["1902_winter_adjustment"]["narrative"]["editorial"] = {
        "sections": [
            section("A. Situation entering Winter", [claim("After the fall retreats, Austria held Rumania but had lost the Greek position and faced a required reduction; Russia held Budapest and Galicia, while Turkey held Greece. Italy remained on four centers with Venice and Tunis held, a fleet in Eastern Mediterranean, and no unit in Ionian Sea. These are public board facts at the adjustment boundary.", public("1902_winter_adjustment", "Winter 1902 board before-state"))], claim("Winter would reveal how much of the fall reversal became permanent force." , public("1902_winter_adjustment", "Winter 1902 public adjudication"))),
            section("B. Intentions, beliefs, and plans", [claim("Helena told Birsan that Austria had to disband and proposed continuing the Venice–Trieste–Adriatic hands-off arrangement into 1903. Major told Birsan that Turkey would build a Smyrna fleet in response to the Eastern Mediterranean contest. These are private statements to Birsan, not a claim that either opponent accepted the other’s terms.", message("1902_winter_negotiation_helena_0", "Message from Helena to Birsan"), message("1902_winter_negotiation_major_1", "Message from Major to Birsan"))], claim("The adjustment orders would provide the public evidence of the immediate choices." , public("1902_winter_adjustment", "Winter 1902 public adjudication"))),
            section("C. Diplomacy and commitments", [claim("Birsan asked Helena to keep Trieste defensive and asked Major to renegotiate the Mediterranean boundary after Italy’s Eastern Mediterranean entry. These messages preserve the proposals and the changed bargaining language, but do not establish an agreed partition or explain the subsequent adjustments by themselves.", message("1902_winter_negotiation_birsan_0", "Message from Birsan to Helena"), message("1902_winter_negotiation_birsan_2", "Message from Birsan to Major"))], claim("The correspondences frame the pressure; the official orders state the outcome." , public("1902_winter_adjustment", "Winter 1902 public adjudication"))),
            section("D. Orders and adjudicated result", [claim("Austria submitted one disband, removing the unit that had been dislodged from Greece, and Turkey submitted BUILD F Smy. Italy had no adjustment because its unit count and center count were level. The adjudicated order record is public and direct on those points.", order("1902_winter_adjustment:adjustment::austria", "Austria’s Winter 1902 disband"), order("1902_winter_adjustment:adjustment::turkey", "Turkey’s Winter 1902 build"), public("1902_winter_adjustment", "Winter 1902 public adjudication")), claim("The after-state thus kept an Austrian force in Albania and placed a new Turkish fleet in Smyrna, rather than erasing either side of the eastern-Mediterranean problem.", public("1902_winter_adjustment", "Winter 1902 board after-state"))], claim("The adjustment reduced Austria but also made Turkey’s maritime capacity more explicit." , public("1902_winter_adjustment", "Winter 1902 board after-state"))),
            section("E. Reactions and what changed", [claim("Birsan’s private winter reflection called the new Smyrna fleet evidence that the eastern Mediterranean was contested and cautioned that Austria’s single disband did not make Trieste free. That belongs to Birsan’s postgame-private assessment, while the reader can independently inspect the public build and disband.", record("1902_winter_adjustment:birsan:reflection", "Birsan’s private Winter reflection"), public("1902_winter_adjustment", "Winter 1902 public adjudication")), claim("By the end of 1902, the record supports a restrained conclusion: Austria had been checked, Russia and Turkey had grown in the Balkan theater, and Italy still had open but contested routes. It does not prove a fixed coalition or a single inevitable next move.", public("1902_winter_adjustment", "Winter 1902 board after-state"), postgame("Postgame chronology"))], claim("Spring 1903 inherits a board of active options rather than a completed explanation." , public("1902_winter_adjustment", "Winter 1902 board after-state"))),
        ]
    }
